import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test } from "node:test";

import { getFreeDrawSvgPath, type FreedrawElement } from "../render/excalidraw-freedraw";

// Generated by running Excalidraw v0.18.1's own getFreeDrawSvgPath (renderElement.ts,
// verbatim) on this fixed point set, with perfect-freehand 1.2.3. The repo is
// pinned to 1.2.0, which reproduces this golden exactly, so it is not regenerated.
type Golden = { points: number[][]; out: Record<string, string> };
const g = JSON.parse(
  readFileSync(new URL("./fixtures/excalidraw-freedraw.golden.json", import.meta.url), "utf8"),
) as Golden;

function element(over: Partial<FreedrawElement>): FreedrawElement {
  return {
    points: g.points,
    pressures: g.points.map(() => 0.5),
    strokeWidth: 4,
    simulatePressure: true,
    lastCommittedPoint: [0, 0],
    ...over,
  };
}

test("matches Excalidraw output for a sparse arc, mouse pressure, width 2", () => {
  assert.equal(getFreeDrawSvgPath(element({ strokeWidth: 2 })), g.out.sparseArcMouse);
});

test("matches Excalidraw output at width 4 (the default pen)", () => {
  assert.equal(getFreeDrawSvgPath(element({ strokeWidth: 4 })), g.out.sparseArcMouse4);
});

test("matches Excalidraw output for real pen pressure (simulatePressure false)", () => {
  const pressures = g.points.map((_, i) => 0.2 + (i / 30) * 0.6);
  assert.equal(
    getFreeDrawSvgPath(element({ strokeWidth: 8, simulatePressure: false, pressures })),
    g.out.penPressure8,
  );
});

test("matches Excalidraw output for a single point", () => {
  assert.equal(
    getFreeDrawSvgPath(element({ points: [[5, 5]], pressures: [0.5], strokeWidth: 2 })),
    g.out.dotOne,
  );
});

test("matches Excalidraw output while the stroke is still wet (no lastCommittedPoint)", () => {
  assert.equal(getFreeDrawSvgPath(element({ lastCommittedPoint: null })), g.out.wetNoLast);
});

test("is a closed quadratic path: Q segments, one closing L, then Z", () => {
  const d = getFreeDrawSvgPath(element({}));
  assert.ok(d.startsWith("M"));
  assert.ok(d.endsWith("Z"));
  assert.equal(d.match(/ L /g)?.length, 1);
  assert.ok(d.includes(" Q"));
});

test("gives finite numbers at the two smallest pen sizes", () => {
  for (const width of [2, 4]) {
    const d = getFreeDrawSvgPath(element({ strokeWidth: width }));
    assert.doesNotMatch(d, /NaN|Infinity/);
    assert.ok(d.length > 100);
  }
});
